const defaults={"stages": [{"id": "heels", "time": "16:30 – 17:15", "title": "Heels", "teacher": "Eleonora · Fra palo e realtà", "type": "WORKSHOP"}, {"id": "linea", "time": "17:15 – 18:00", "title": "Salsa in linea", "teacher": "Davide e Simona · Salsa Buena", "type": "WORKSHOP"}, {"id": "cubana", "time": "18:00 – 18:45", "title": "Salsa cubana", "teacher": "Daniele e Laura · Terra Latina", "type": "WORKSHOP"}, {"id": "flow", "time": "18:45 – 19:30", "title": "Bachata Sensual", "teacher": "Michele e Silvia · Latin Flow", "type": "WORKSHOP"}, {"id": "dinner", "time": "19:30 – 20:00", "title": "Pizza time", "teacher": "Buffet pizza · Pizza 99 · Su prenotazione", "type": "FOOD & FRIENDS"}, {"id": "party", "time": "20:00 – 24:00", "title": "Social Party", "teacher": "DJ Markino", "type": "SALSA & BACHATA"}], "passes": [{"id": "full", "name": "Tutto incluso", "price": 18, "desc": "Tutti gli stage, buffet pizza e serata insieme.", "items": ["Tutti e 4 gli stage", "Buffet pizza su prenotazione", "Un drink", "Social party"], "stages": ["heels", "linea", "cubana", "flow"]}, {"id": "evening", "name": "Serata", "price": 10, "desc": "La musica di DJ Markino e un drink in compagnia.", "items": ["Ingresso alla serata", "Un drink", "Social party · 20:00 – 24:00"], "stages": []}]};
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(k,d){try{return JSON.parse(localStorage.getItem(k))||d}catch{return d}}let cfg=read('park-config-v2',defaults),records=read('park-records',[]);cfg.stages.forEach(s=>{if(s.id==='cubana')s.teacher=s.teacher.replace('Tierra Latina','Terra Latina')});const eur=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
function render(){ $('#schedule').innerHTML=cfg.stages.map(s=>`<div class="schedule-row event-band"><div class="band-info"><span class="time">${esc(s.time)}</span><h3>${esc(s.title)}</h3><p>${esc(s.teacher)}</p></div>${s.id==='dinner'?`<div class="band-art pizza-art"><img src="assets/pizza99.webp" alt="Pizza 99 · Sponsor Pizza time" loading="lazy"></div>`:s.id==='flow'?`<div class="band-art flow-art"><img class="terra-logo" src="assets/latin-flow-logo.webp" alt="Latin Flow Academy" loading="lazy"><img class="terra-couple" src="assets/michele-silvia.webp" alt="Michele e Silvia · Latin Flow" loading="lazy"></div>`:s.id==='heels'?`<div class="band-art heels-art"><img class="terra-logo" src="assets/fra-palo-realta-logo.webp" alt="Fra Palo e Realtà A.S.D." loading="lazy"><img class="terra-couple" src="assets/eleonora.webp" alt="Eleonora · Heels" loading="lazy"></div>`:s.id==='linea'?`<div class="band-art buena-art"><img class="terra-logo" src="assets/salsa-buena-logo.webp" alt="Salsa Buena" loading="lazy"><img class="terra-couple" src="assets/davide-simona.webp" alt="Davide e Simona di Salsa Buena" loading="lazy"></div>`:s.id==='cubana'?`<div class="band-art"><img class="terra-logo" src="assets/terra-latina-logo.webp" alt="Terra Latina · Escuela de baile · Ravenna" loading="lazy"><img class="terra-couple" src="assets/daniele-laura.webp" alt="Daniele e Laura di Terra Latina" loading="lazy"></div>`:`<span class="tag">${esc(s.type)}</span>`}</div>`).join('');$('#passes').innerHTML=cfg.passes.map(p=>`<article class="pass ${esc(p.id)}"><span class="pass-name">${esc(p.name.toUpperCase())}</span><h3>${eur(p.price)} <small>/ persona</small></h3><p>${esc(p.desc)}</p><ul>${p.items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul><button data-pass="${esc(p.id)}">Scelgo ${esc(p.name)} ↗</button></article>`).join('');$('#passSelect').innerHTML=cfg.passes.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${eur(p.price)}</option>`).join('');document.querySelectorAll('[data-pass]').forEach(b=>b.onclick=()=>{$('#passSelect').value=b.dataset.pass;update();$('#prenota').scrollIntoView({behavior:'smooth'})});update()}
function update(){const p=cfg.passes.find(p=>p.id===$('#passSelect').value);$('#total').textContent=eur(p.price*Number($('#qty').value||0));$('#workshops').innerHTML=p.stages.length?p.stages.map(id=>{const s=cfg.stages.find(s=>s.id===id);return s?`<label class="check"><input type="checkbox" name="workshop" value="${esc(id)}" checked>${esc(s.title)}</label>`:''}).join(''):'<p style="font-size:12px;margin:0">Il pass Serata include ingresso e drink. Scegli Tutto incluso per gli stage e il buffet pizza.</p>'}
$('#passSelect').onchange=update;$('#qty').oninput=()=>{const p=cfg.passes.find(p=>p.id===$('#passSelect').value);$('#total').textContent=eur(p.price*Number($('#qty').value||0))};
$('#form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p=cfg.passes.find(p=>p.id===f.get('pass')),workshops=f.getAll('workshop');if(p.stages.length&&!workshops.length){$('#result').textContent='Scegli almeno un workshop di interesse.';return}const r={id:crypto.randomUUID(),date:new Date().toISOString(),name:f.get('name').trim(),phone:f.get('phone').trim(),pass:p.name,qty:Number(f.get('qty')),total:p.price*Number(f.get('qty')),workshops:workshops.map(id=>cfg.stages.find(s=>s.id===id)?.title).join(', '),notes:f.get('notes').trim()};if(!r.name)return;try{records.push(r);localStorage.setItem('park-records',JSON.stringify(records));$('#result').textContent=`Prova salvata: ${r.qty} partecipante/i, pass ${r.pass}, ${eur(r.total)}. Nessuna prenotazione reale inviata.`;e.target.reset();update()}catch{records.pop();$('#result').textContent='Impossibile salvare su questo browser. Nessuna prenotazione registrata.'}};
$('#manage').onclick=()=>{$('#config').value=JSON.stringify(cfg,null,2);friendly();list();$('#admin').showModal()};$('#closeAdmin').onclick=()=>$('#admin').close();$('#editTab').onclick=()=>{$('#editor').hidden=false;$('#bookings').hidden=true};$('#listTab').onclick=()=>{$('#editor').hidden=true;$('#bookings').hidden=false;list()};
$('#saveConfig').onclick=()=>{try{const c=JSON.parse($('#config').value);if(!Array.isArray(c.stages)||!Array.isArray(c.passes)||c.passes.length!==2)throw Error('Servono stages e due pacchetti passes.');if(c.stages.some(s=>!['id','time','title','teacher','type'].every(k=>typeof s[k]==='string'))||new Set(c.stages.map(s=>s.id)).size!==c.stages.length)throw Error('Controlla i campi e gli identificativi degli stage.');if(c.passes.some(p=>!['full','evening'].includes(p.id)||!Number.isFinite(p.price)||p.price<0||typeof p.name!=='string'||typeof p.desc!=='string'||!Array.isArray(p.items)||!p.items.every(i=>typeof i==='string')||!Array.isArray(p.stages)||p.stages.some(id=>!c.stages.find(s=>s.id===id)))||new Set(c.passes.map(p=>p.id)).size!==2)throw Error('Controlla prezzi, pacchetti e stage inclusi.');localStorage.setItem('park-config-v2',JSON.stringify(c));cfg=c;render();$('#adminStatus').textContent='Modifiche salvate in questo browser.'}catch(e){$('#adminStatus').textContent='Configurazione non salvata: '+e.message}};
function list(){$('#records').innerHTML=records.length?records.map(r=>`<article><b>${esc(r.name)}</b> · ${esc(r.pass)} × ${r.qty} · ${eur(r.total)}<p>${esc(r.phone)}<br>${esc(r.workshops)}<br>${esc(r.notes)}</p><button data-delete="${r.id}">Elimina prova</button></article>`).join(''):'<p>Nessuna prenotazione di prova.</p>';document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{records=records.filter(r=>r.id!==b.dataset.delete);localStorage.setItem('park-records',JSON.stringify(records));list()})}
$('#export').onclick=()=>{const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replace(/"/g,'""')+'"';const csv='\ufeff'+[['Nome','Telefono','Pass','Persone','Totale','Stage','Note','Data'],...records.map(r=>[r.name,r.phone,r.pass,r.qty,r.total,r.workshops,r.notes,r.date])].map(row=>row.map(cell).join(';')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download='park-latino-prenotazioni-demo.csv';a.click();URL.revokeObjectURL(u)};render();

function friendly(){const target=$('#friendlyEditor');target.innerHTML='<h3>Programma</h3>'+cfg.stages.map((s,i)=>`<div class="stage-edit"><div class="two"><label>Stage / attività<input data-stage="${i}" data-key="title" value="${esc(s.title)}"></label><label>Orario<input data-stage="${i}" data-key="time" value="${esc(s.time)}"></label></div><label>Insegnanti / descrizione<input data-stage="${i}" data-key="teacher" value="${esc(s.teacher)}"></label><button type="button" data-remove="${i}">Rimuovi attività</button></div>`).join('')+'<button type="button" id="addStage">+ Aggiungi attività</button><h3>Prezzi e inclusioni</h3>'+cfg.passes.map((p,i)=>`<div class="stage-edit"><div class="two"><label>Pacchetto<input data-package="${i}" data-key="name" value="${esc(p.name)}"></label><label>Prezzo €<input type="number" min="0" data-package="${i}" data-key="price" value="${p.price}"></label></div><label>Inclusioni (una per riga)<textarea data-package="${i}" data-key="items">${esc(p.items.join('\n'))}</textarea></label><span style="font-size:11px">Stage selezionabili nella prenotazione</span>${cfg.stages.filter(s=>s.type==='WORKSHOP').map(st=>`<label class="check"><input type="checkbox" data-package-stage="${i}" value="${esc(st.id)}" ${p.stages.includes(st.id)?'checked':''}>${esc(st.title)}</label>`).join('')}</div>`).join('');target.querySelectorAll('input[data-stage],input[data-package],textarea[data-package],input[data-package-stage]').forEach(el=>el.oninput=()=>{let c=JSON.parse($('#config').value);if(el.dataset.stage!==undefined)c.stages[el.dataset.stage][el.dataset.key]=el.value;else if(el.dataset.package!==undefined)c.passes[el.dataset.package][el.dataset.key]=el.dataset.key==='price'?Number(el.value):el.dataset.key==='items'?el.value.split('\n').filter(Boolean):el.value;else{const p=c.passes[el.dataset.packageStage];p.stages=el.checked?[...new Set([...p.stages,el.value])]:p.stages.filter(id=>id!==el.value)}$('#config').value=JSON.stringify(c,null,2)});target.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const c=JSON.parse($('#config').value),id=c.stages[Number(b.dataset.remove)].id;c.stages.splice(Number(b.dataset.remove),1);c.passes.forEach(p=>p.stages=p.stages.filter(s=>s!==id));cfg=c;$('#config').value=JSON.stringify(c,null,2);friendly()});$('#addStage').onclick=()=>{cfg=JSON.parse($('#config').value);cfg.stages.push({id:'stage-'+Date.now(),time:'Da definire',title:'Nuovo workshop',teacher:'Da annunciare',type:'WORKSHOP'});$('#config').value=JSON.stringify(cfg,null,2);friendly()}};
